theme.css:
#wemd{color:#555555;background-color:#fffef8;font-family:'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Noto Sans SC', 'Microsoft YaHei', sans-serif;font-size:14px;line-height:1.9;letter-spacing:0.02em;text-align:justify;padding:28px 20px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1em;text-indent:0}
#wemd h1{font-size:26px;font-weight:900;color:#1a1a1a;margin-top:2em;margin-bottom:1em;text-align:left}
#wemd h2{font-size:20px;font-weight:800;color:#1a1a1a;margin-top:2.4em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid #1a1a1a;padding-bottom:.4em}
#wemd h3{font-size:16px;font-weight:700;color:#1a1a1a;margin-top:1.8em;margin-bottom:0.6em}
#wemd h3::before{content:"· ";color:#059669}
#wemd h4{font-size:14px;font-weight:600;color:#888888;margin-top:1.4em;margin-bottom:0.5em}
#wemd blockquote{border-left:4px solid #059669;background:#F0FDF4;padding:14px 20px;color:#1a1a1a;font-style:normal;margin:1.2em 0}
#wemd code{background-color:#F3F4F6;color:#1F2937;padding:2px 6px;border-radius:4px;font-size:0.9em;font-family:ui-monospace, 'Cascadia Code', 'Fira Code', Menlo, Monaco, Consolas, monospace}
#wemd pre{background:#F3F4F6;border-radius:6px;padding:16px 20px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid #eeeeee;padding:10px 14px}
#wemd th{background:#F0FDF4}
#wemd tr:nth-child(even){background:#fffef8}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:6px}
#wemd li::marker{color:#059669}
#wemd hr{border:0;border-top:1px dashed #A7F3D0;margin:2em 0;width:100%}
#wemd img{max-width:100%;height:auto;border-radius:4px}
#wemd figcaption{font-size:12px;color:#999999;text-align:center}
#wemd a{color:#059669;text-decoration:none}
#wemd strong{color:#059669;font-weight:700}
#wemd mark{background:#A7F3D0;padding:2px 4px;border-radius:2px}
